def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> int:
        total = 0
        for i, char in enumerate(isbn):
            if char == '-':
                continue
            digit = int(char)
            if i % 2 == 0:
                total += digit
            else:
                total += digit * 3
        return total % 10

    # Remove hyphens and convert to list of integers
    isbn_digits = [int(char) if char != '-' else 0 for char in isbn]

    # Calculate the current checksum
    current_checksum = calculate_checksum(isbn)

    # Calculate the required checksum digit
    required_checksum = (10 - current_checksum) % 10

    # Check if the last character is 'X' and adjust the list accordingly
    if isbn[-1] == 'X':
        isbn_digits[-1] = 10
    else:
        isbn_digits[-1] = int(isbn[-1])

    # Calculate the checksum with the last digit as the required checksum
    adjusted_checksum = calculate_checksum(''.join(map(str, isbn_digits)))

    # If the checksum is correct, return "Right"
    if adjusted_checksum == 0:
        return "Right"

    # If the checksum is incorrect, return the corrected ISBN
    isbn_digits[-1] = required_checksum
    return '-'.join(map(str, isbn_digits))
