def count_coprime_pairs(x0: int, y0: int) -> int:
    count = 0
    quotient = y0 // x0
    for a in range(1, quotient + 1):
        if quotient % a == 0:
            b = quotient // a
            if a == b:
                count += 1
            elif gcd(a, b) == 1:
                count += 2
    return count

def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a
