def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Initialize the list to store the length of the longest increasing subsequence ending at each index
    lis = [1] * n

    # Compute the LIS values from left to right
    for i in range(1, n):
        for j in range(i):
            if heights[i] > heights[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    # Initialize the list to store the length of the longest decreasing subsequence starting at each index
    lds = [1] * n

    # Compute the LDS values from right to left
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if heights[i] > heights[j] and lds[i] < lds[j] + 1:
                lds[i] = lds[j] + 1

    # Find the maximum value of lis[i] + lds[i] - 1 for all i
    max_length = 0
    for i in range(n):
        max_length = max(max_length, lis[i] + lds[i] - 1)

    # The minimum number of students to leave is the total number of students minus the maximum length of the choir formation
    return n - max_length
```
